/**
 * Upload avatar
 * POST /api/users/me/avatar
 */
app.post('/api/users/me/avatar', requireAuth, async (req, res, next) => {
  try {
    const { avatar_base64 } = req.body;

    if (!avatar_base64) {
      return res.status(400).json({ success: false, message: 'Vui lÃ²ng cung cáº¥p áº£nh' });
    }

    // Decode base64 vÃ  upload lÃªn Supabase Storage
    const base64Data = avatar_base64.replace(/^data:image\/\w+;base64,/, '');
    const buffer = Buffer.from(base64Data, 'base64');

    const fileName = `avatars/${req.user.id}_${Date.now()}.jpg`;

    const { data: uploadData, error: uploadError } = await supabase.storage
      .from('avatars')
      .upload(fileName, buffer, {
        contentType: 'image/jpeg',
        upsert: true
      });

    if (uploadError) {
      console.error('Upload error:', uploadError);
      // Náº¿u bucket chÆ°a tá»“n táº¡i, lÆ°u base64 trá»±c tiáº¿p vÃ o DB
      const { data, error } = await supabase
        .from('users')
        .update({ avatar_url: avatar_base64 })
        .eq('id', req.user.id)
        .select('avatar_url')
        .single();

      if (error) throw error;
      return res.json({ success: true, data: { avatar_url: data.avatar_url } });
    }

    // Láº¥y public URL
    const { data: { publicUrl } } = supabase.storage
      .from('avatars')
      .getPublicUrl(fileName);

    // Cáº­p nháº­t avatar_url trong users
    const { error: updateError } = await supabase
      .from('users')
      .update({ avatar_url: publicUrl })
      .eq('id', req.user.id);

    if (updateError) throw updateError;

    console.log(`ðŸ“· Avatar uploaded for ${req.user.email}`);
    res.json({ success: true, data: { avatar_url: publicUrl } });
  } catch (error) {
    console.error('Error uploading avatar:', error);
    next(error);
  }
});

// ============ ADMIN APIs (Chá»‰ Admin má»›i Ä‘Æ°á»£c dÃ¹ng) ============

// Láº¥y danh sÃ¡ch nhÃ¢n sá»± (Teacher, Manager)
app.get('/api/admin/staff', requireAuth, async (req, res, next) => {
  try {
    const { role, centerId, search, limit = 50, page = 1 } = req.query;

    // Pagination
    const pageNum = parseInt(page) || 1;
    const limitNum = Math.min(parseInt(limit) || 50, 100);
    const offset = (pageNum - 1) * limitNum;

    // ====== PERMISSION CHECK ======
    const { effectiveCenterId, error: permError } = getEffectiveCenterId(req.user, centerId);
    if (permError) {
      return res.status(403).json({ success: false, message: permError });
    }

    // Select fields - use explicit FK hint to avoid ambiguity
    const selectFields = `
      id,
      email,
      full_name,
      phone,
      avatar_url,
      status,
      hourly_rate,
      center_id,
      created_at,
      roles (id, code, name),
      centers!users_center_id_fkey (id, name)
    `;

    let query;

    // Filter theo role náº¿u cÃ³
    if (role) {
      // Láº¥y role_id tá»« code
      const { data: roleData } = await supabase
        .from('roles')
        .select('id')
        .eq('code', role)
        .single();

      if (roleData) {
        query = supabase
          .from('users')
          .select(selectFields, { count: 'exact' })
          .eq('role_id', roleData.id)
          .order('created_at', { ascending: false });
      } else {
        return res.json({ success: true, data: [], pagination: { total: 0, page: pageNum, limit: limitNum } });
      }
    } else {
      // Láº¥y táº¥t cáº£ staff (khÃ´ng pháº£i STUDENT vÃ  khÃ´ng pháº£i SUPER_ADMIN vÃ¬ SA khÃ´ng xuáº¥t hiá»‡n trong list nhÃ¢n viÃªn)
      const { data: excludeRoles } = await supabase
        .from('roles')
        .select('id')
        .in('code', ['STUDENT']);

      const excludeRoleIds = excludeRoles?.map(r => r.id) || [];

      if (excludeRoleIds.length > 0) {
        query = supabase
          .from('users')
          .select(selectFields, { count: 'exact' })
          .not('role_id', 'in', `(${excludeRoleIds.join(',')})`)
          .order('created_at', { ascending: false });
      } else {
        query = supabase
          .from('users')
          .select(selectFields, { count: 'exact' })
          .order('created_at', { ascending: false });
      }
    }

    // ====== CENTER FILTER ======
    if (effectiveCenterId) {
      query = query.eq('center_id', effectiveCenterId);
    }

    // ====== SEARCH FILTER ======
    if (search && search.trim().length >= 2) {
      const term = search.trim().toLowerCase();
      query = query.or(`full_name.ilike.%${term}%,email.ilike.%${term}%,phone.ilike.%${term}%`);
    }

    // ====== PAGINATION ======
    const { data, error, count } = await query;
    if (error) throw error;

    res.json({
      success: true,
      data: data || [],
      pagination: {
        total: count || 0,
        page: pageNum,
        limit: limitNum,
        totalPages: Math.ceil((count || 0) / limitNum)
      }
    });
  } catch (error) {
    console.error('Error fetching staff:', error);
    next(error);
  }
});

