/**
 * PATCH /api/admin/centers/:id/manager - GÃ¡n/Ä‘á»•i quáº£n lÃ½ trung tÃ¢m
 */
app.patch('/api/admin/centers/:id/manager', requireAuth, requireRole(['SUPER_ADMIN']), async (req, res, next) => {
  try {
    const { id } = req.params;
    const { manager_id } = req.body;

    console.log(`ðŸ‘” SUPER_ADMIN ${req.user.email} gÃ¡n manager cho center: ${id}`);

    // Validate manager
    if (manager_id) {
      const { data: manager, error: managerError } = await supabase
        .from('users')
        .select('id, full_name, roles(code)')
        .eq('id', manager_id)
        .single();

      if (managerError || !manager) {
        return res.status(400).json({
          success: false,
          message: 'KhÃ´ng tÃ¬m tháº¥y ngÆ°á»i dÃ¹ng'
        });
      }

      if (manager.roles?.code !== 'CENTER_MANAGER') {
        return res.status(400).json({
          success: false,
          message: 'NgÆ°á»i Ä‘Æ°á»£c chá»n pháº£i cÃ³ vai trÃ² Quáº£n lÃ½ (CENTER_MANAGER)'
        });
      }
    }

    // Láº¥y old manager Ä‘á»ƒ remove
    const { data: center } = await supabase
      .from('centers')
      .select('manager_id')
      .eq('id', id)
      .single();

    // Update center
    const { data, error } = await supabase
      .from('centers')
      .update({ manager_id: manager_id || null })
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;

    // Update users
    if (center?.manager_id && center.manager_id !== manager_id) {
      await supabase.from('users').update({ center_id: null }).eq('id', center.manager_id);
    }
    if (manager_id) {
      await supabase.from('users').update({ center_id: id }).eq('id', manager_id);
    }

    AuditLogService.log({ ...getAuditContext(req), action: 'UPDATE', tableName: 'centers', recordId: id, newValues: { manager_id: req.body.manager_id } });

    res.json({
      success: true,
      message: manager_id ? 'ÄÃ£ gÃ¡n quáº£n lÃ½ cho trung tÃ¢m' : 'ÄÃ£ xÃ³a quáº£n lÃ½ trung tÃ¢m',
      data
    });
  } catch (error) {
    console.error('Error assigning manager:', error);
    next(error);
  }
});

