// Láº¥y chi tiáº¿t há»c viÃªn (kÃ¨m enrollments, invoices, attendance)
app.get('/api/admin/students/:id', requireAuth, async (req, res, next) => {
  try {
    const { id } = req.params;

    // Láº¥y thÃ´ng tin user
    const { data: user, error: userError } = await supabase
      .from('users')
      .select(`
        id,
        email,
        full_name,
        phone,
        avatar_url,
        status,
        created_at,
        updated_at,
        parent_name,
        parent_phone,
        parent_email,
        parent_relationship,
        date_of_birth,
        roles (id, code, name)
      `)
      .eq('id', id)
      .single();

    if (userError || !user) {
      return res.status(404).json({
        success: false,
        message: 'KhÃ´ng tÃ¬m tháº¥y há»c viÃªn'
      });
    }

    // Kiá»ƒm tra cÃ³ pháº£i STUDENT khÃ´ng
    if (user.roles?.code !== 'STUDENT') {
      return res.status(400).json({
        success: false,
        message: 'User nÃ y khÃ´ng pháº£i há»c viÃªn'
      });
    }

    // Láº¥y danh sÃ¡ch lá»›p Ä‘ang há»c (enrollments)
    const { data: enrollments } = await supabase
      .from('enrollments')
      .select(`
        id,
        status,
        enrolled_at,
        tuition_fee,
        discount_amount,
        paid_amount,
        classes (
          id,
          code,
          name,
          status,
          start_date,
          end_date,
          courses (id, title, category)
        )
      `)
      .eq('student_id', id)
      .order('enrolled_at', { ascending: false });

    // Láº¥y danh sÃ¡ch hÃ³a Ä‘Æ¡n
    const { data: invoices } = await supabase
      .from('invoices')
      .select(`
        id,
        invoice_code,
        final_amount,
        paid_amount,
        status,
        due_date,
        created_at
      `)
      .eq('student_id', id)
      .order('created_at', { ascending: false })
      .limit(10);

    // Láº¥y danh sÃ¡ch chá»©ng chá»‰ (bao gá»“m certificate_types)
    const { data: certificates } = await supabase
      .from('certificates')
      .select(`
        id,
        certificate_number,
        completion_date,
        issued_at,
        status,
        grade,
        download_url,
        scores,
        external_id,
        file_url,
        expires_at,
        courses (id, title, category),
        certificate_types (
          id, 
          code, 
          name, 
          category,
          issuing_organization,
          is_external,
          is_internal,
          score_config
        )
      `)
      .eq('student_id', id)
      .order('issued_at', { ascending: false });

    // TÃ­nh thá»‘ng kÃª
    const activeEnrollments = (enrollments || []).filter(e => e.status === 'active');
    const completedEnrollments = (enrollments || []).filter(e => e.status === 'completed');

    const totalPaid = (invoices || []).reduce((sum, inv) => sum + (inv.paid_amount || 0), 0);
    const totalDebt = (invoices || [])
      .filter(inv => inv.status !== 'paid' && inv.status !== 'cancelled')
      .reduce((sum, inv) => sum + ((inv.final_amount || 0) - (inv.paid_amount || 0)), 0);

    // Láº¥y thá»‘ng kÃª Ä‘iá»ƒm danh (30 ngÃ y gáº§n nháº¥t)
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    const { data: attendanceData } = await supabase
      .from('attendance')
      .select('id, status, enrollment_id')
      .in('enrollment_id', (enrollments || []).map(e => e.id))
      .gte('session_date', thirtyDaysAgo.toISOString().split('T')[0]);

    const attendanceStats = {
      total: attendanceData?.length || 0,
      present: attendanceData?.filter(a => a.status === 'present').length || 0,
      absent: attendanceData?.filter(a => a.status === 'absent').length || 0,
      late: attendanceData?.filter(a => a.status === 'late').length || 0,
    };

    res.json({
      success: true,
      data: {
        ...user,
        enrollments: enrollments || [],
        invoices: invoices || [],
        certificates: certificates || [],
        stats: {
          activeClasses: activeEnrollments.length,
          completedClasses: completedEnrollments.length,
          totalClasses: (enrollments || []).length,
          totalPaid,
          totalDebt,
          attendance: attendanceStats,
          certificatesCount: (certificates || []).length
        }
      }
    });
  } catch (error) {
    console.error('Error fetching student detail:', error);
    next(error);
  }
});

