// Láº¥y danh sÃ¡ch documents cá»§a má»™t lá»›p
app.get('/api/admin/classes/:classId/documents', requireAuth, async (req, res, next) => {
  try {
    const { classId } = req.params;
    const { type, search, page = 1, limit = 50 } = req.query;

    let query = supabase
      .from('documents')
      .select(`
        *,
        courses (id, code, title),
        uploaded_by_user:users!documents_uploaded_by_fkey (id, full_name, email)
      `, { count: 'exact' })
      .eq('class_id', classId)
      .order('created_at', { ascending: false });

    if (type) {
      query = query.eq('type', type);
    }
    if (search) {
      query = query.or(`title.ilike.%${search}%,description.ilike.%${search}%`);
    }

    // Pagination
    const offset = (page - 1) * limit;
    query = query.range(offset, offset + parseInt(limit) - 1);

    const { data, error, count } = await query;
    if (error) throw error;

    res.json({
      success: true,
      data: data || [],
      pagination: {
        total: count || 0,
        page: parseInt(page),
        limit: parseInt(limit),
        totalPages: Math.ceil((count || 0) / limit)
      }
    });
  } catch (error) {
    console.error('Error fetching class documents:', error);
    next(error);
  }
});

