app.get('/api/payments/pending', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { center_id } = req.query;
    const { effectiveCenterId, error: permError } = getEffectiveCenterId(req.user, center_id || null);
    if (permError) {
      return res.status(403).json({ success: false, message: permError });
    }

    const { data: payments, error } = await supabase
      .from('payments')
      .select(`
        *,
        invoice:invoice_id(
          id, invoice_code, final_amount, paid_amount,
          student:student_id(id, full_name, email, phone),
          class:class_id(id, center_id)
        ),
        received_by_user:received_by(id, full_name)
      `)
      .eq('verification_status', 'pending')
      .eq('payment_method', 'bank_transfer')
      .order('created_at', { ascending: true });

    if (error) throw error;

    let filtered = payments || [];
    if (effectiveCenterId) {
      filtered = filtered.filter((item) => item.invoice?.class?.center_id === effectiveCenterId);
    }

    res.json({
      success: true,
      data: filtered,
      count: filtered.length
    });
  } catch (error) {
    console.error('Error fetching pending payments:', error);
    next(error);
  }
});

// ============================================
// GET /api/transactions - Full transactions list (Tab Giao dá»‹ch)
// ============================================
app.get('/api/transactions', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const {
      status,       // all | pending | verified | rejected
      method,       // all | cash | bank_transfer
      dateStart,
      dateEnd,
      search,
      page = 1,
      limit = 20,
      center_id
    } = req.query;

    const { effectiveCenterId, error: permError } = getEffectiveCenterId(req.user, center_id || null);
    if (permError) {
      return res.status(403).json({ success: false, message: permError });
    }

    // Build query
    let query = supabase
      .from('payments')
      .select(`
        *,
        invoice:invoice_id(
          id, invoice_code, final_amount, paid_amount, status,
          student:student_id(id, full_name, email, phone),
          class:class_id(id, name, center_id)
        ),
        received_by_user:received_by(id, full_name),
        verified_by_user:verified_by(id, full_name)
      `);

    // Filter by verification status
    if (status && status !== 'all') {
      query = query.eq('verification_status', status);
    }

    // Filter by payment method
    if (method && method !== 'all') {
      query = query.eq('payment_method', method);
    }

    // Filter by date range
    if (dateStart) {
      query = query.gte('created_at', `${dateStart}T00:00:00`);
    }
    if (dateEnd) {
      query = query.lte('created_at', `${dateEnd}T23:59:59`);
    }

    query = query
      .order('created_at', { ascending: false });

    const { data: transactions, error } = await query;

    if (error) throw error;

    let filtered = transactions || [];

    if (effectiveCenterId) {
      filtered = filtered.filter((item) => item.invoice?.class?.center_id === effectiveCenterId);
    }

    if (search && search.trim()) {
      const searchLower = search.trim().toLowerCase();
      filtered = filtered.filter((item) => {
        const invoiceCode = item.invoice?.invoice_code?.toLowerCase() || '';
        const studentName = item.invoice?.student?.full_name?.toLowerCase() || '';
        const studentEmail = item.invoice?.student?.email?.toLowerCase() || '';
        const studentPhone = item.invoice?.student?.phone || '';
        const referenceCode = item.reference_code?.toLowerCase() || '';
        const noteText = item.notes?.toLowerCase() || '';

        return (
          invoiceCode.includes(searchLower)
          || studentName.includes(searchLower)
          || studentEmail.includes(searchLower)
          || studentPhone.includes(searchLower)
          || referenceCode.includes(searchLower)
          || noteText.includes(searchLower)
        );
      });
    }

    const pageNum = parseInt(page, 10) || 1;
    const limitNum = parseInt(limit, 10) || 20;
    const from = (pageNum - 1) * limitNum;
    const paginated = filtered.slice(from, from + limitNum);

    const summary = {
      total: filtered.length,
      totalPending: filtered.filter(s => s.verification_status === 'pending').length,
      totalVerified: filtered.filter(s => s.verification_status === 'verified').length,
      totalRejected: filtered.filter(s => s.verification_status === 'rejected').length,
      pendingAmount: filtered
        .filter(s => s.verification_status === 'pending')
        .reduce((sum, s) => sum + parseFloat(s.amount || 0), 0)
    };

    res.json({
      success: true,
      data: paginated,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: filtered.length,
        totalPages: Math.ceil(filtered.length / limitNum)
      },
      summary
    });
  } catch (error) {
    console.error('Error fetching transactions:', error);
    next(error);
  }
});

// PATCH /api/transactions/bulk-verify - Bulk verify transactions
app.patch('/api/transactions/bulk-verify', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { paymentIds } = req.body;
    const userId = req.user?.id;

    if (!paymentIds || !Array.isArray(paymentIds) || paymentIds.length === 0) {
      return res.status(400).json({
        success: false,
        message: 'Vui lÃ²ng chá»n Ã­t nháº¥t má»™t giao dá»‹ch'
      });
    }

    const { data: candidatePayments, error: fetchError } = await supabase
      .from('payments')
      .select(`
        id,
        verification_status,
        invoice:invoice_id(
          id,
          class:class_id(id, center_id),
          student:student_id(id, center_id)
        )
      `)
      .in('id', paymentIds);

    if (fetchError) throw fetchError;

    const foundIds = new Set((candidatePayments || []).map((item) => item.id));
    const missingIds = paymentIds.filter((id) => !foundIds.has(id));
    if (missingIds.length > 0) {
      return res.status(404).json({
        success: false,
        message: 'Má»™t sá»‘ giao dá»‹ch khÃ´ng tá»“n táº¡i',
        data: { missingIds }
      });
    }

    const unauthorizedIds = [];
    const invalidStatusIds = [];

    for (const payment of candidatePayments || []) {
      const paymentCenterId = payment.invoice?.class?.center_id || payment.invoice?.student?.center_id || null;
      const { error: paymentPermError } = getEffectiveCenterId(req.user, paymentCenterId);

      if (paymentPermError || (req.user.roleCode === 'CENTER_MANAGER' && !paymentCenterId)) {
        unauthorizedIds.push(payment.id);
      }

      if (payment.verification_status !== 'pending') {
        invalidStatusIds.push(payment.id);
      }
    }

    if (unauthorizedIds.length > 0) {
      return res.status(403).json({
        success: false,
        message: 'CÃ³ giao dá»‹ch thuá»™c trung tÃ¢m khÃ¡c, thao tÃ¡c bá»‹ tá»« chá»‘i',
        data: { unauthorizedIds }
      });
    }

    if (invalidStatusIds.length > 0) {
      return res.status(400).json({
        success: false,
        message: 'Chá»‰ cÃ³ thá»ƒ xÃ¡c nháº­n cÃ¡c giao dá»‹ch á»Ÿ tráº¡ng thÃ¡i chá» xÃ¡c minh',
        data: { invalidStatusIds }
      });
    }

    // Filter out payments for invoices already fully paid (prevent constraint violation)
    const validPaymentIds = [];
    const duplicatePaymentIds = [];
    
    for (const payment of candidatePayments || []) {
      const invoiceId = payment.invoice?.id;
      if (!invoiceId) { validPaymentIds.push(payment.id); continue; }
      
      const { data: verifiedPayments } = await supabaseAdmin
        .from('payments')
        .select('amount')
        .eq('invoice_id', invoiceId)
        .eq('verification_status', 'verified');
      const totalVerified = (verifiedPayments || []).reduce((s, p) => s + parseFloat(p.amount || 0), 0);
      
      const { data: inv } = await supabaseAdmin
        .from('invoices')
        .select('final_amount')
        .eq('id', invoiceId)
        .single();
      
      if (inv && totalVerified >= parseFloat(inv.final_amount || 0)) {
        duplicatePaymentIds.push(payment.id);
      } else {
        validPaymentIds.push(payment.id);
      }
    }

    // Auto-reject duplicate payments
    if (duplicatePaymentIds.length > 0) {
      await supabaseAdmin.from('payments').update({
        verification_status: 'rejected',
        rejection_reason: 'HÃ³a Ä‘Æ¡n Ä‘Ã£ Ä‘Æ°á»£c thanh toÃ¡n Ä‘áº§y Ä‘á»§. Giao dá»‹ch trÃ¹ng láº·p.',
        verified_by: userId,
        verified_at: new Date().toISOString()
      }).in('id', duplicatePaymentIds);
    }

    let updated = [];
    if (validPaymentIds.length > 0) {
      // Update valid payments
      const { data, error } = await supabaseAdmin
        .from('payments').update({
        verification_status: 'verified',
        verified_by: userId,
        verified_at: new Date().toISOString()
      })
        .in('id', validPaymentIds)
        .eq('verification_status', 'pending')
        .select();

      if (error) throw error;
      updated = data || [];
    }

    const rejectedCount = duplicatePaymentIds.length;
    const verifiedCount = updated?.length || 0;
    let message = `ÄÃ£ xÃ¡c nháº­n ${verifiedCount} giao dá»‹ch`;
    if (rejectedCount > 0) {
      message += `. ${rejectedCount} giao dá»‹ch trÃ¹ng láº·p Ä‘Ã£ bá»‹ tá»« chá»‘i tá»± Ä‘á»™ng.`;
    }
    
    res.json({
      success: true,
      message,
      data: updated,
      count: verifiedCount,
      rejectedCount
    });
  } catch (error) {
    console.error('Error bulk verifying transactions:', error);
    next(error);
  }
});

// PUT /api/invoices/:id - Cáº­p nháº­t hÃ³a Ä‘Æ¡n
app.put('/api/invoices/:id', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { id } = req.params;
    const { amount, discount_amount, due_date, description, invoice_type } = req.body;

    // Láº¥y invoice hiá»‡n táº¡i
    const { data: currentInvoice, error: fetchError } = await supabase
      .from('invoices')
      .select('*')
      .eq('id', id)
      .single();

    if (fetchError || !currentInvoice) {
      return res.status(404).json({ success: false, message: 'KhÃ´ng tÃ¬m tháº¥y hÃ³a Ä‘Æ¡n' });
    }

    // KhÃ´ng cho sá»­a náº¿u Ä‘Ã£ paid hoáº·c cancelled
    if (currentInvoice.status === 'paid') {
      return res.status(400).json({ success: false, message: 'KhÃ´ng thá»ƒ sá»­a hÃ³a Ä‘Æ¡n Ä‘Ã£ thanh toÃ¡n Ä‘á»§' });
    }
    if (currentInvoice.status === 'cancelled') {
      return res.status(400).json({ success: false, message: 'KhÃ´ng thá»ƒ sá»­a hÃ³a Ä‘Æ¡n Ä‘Ã£ há»§y' });
    }

    const updateData = { updated_at: new Date().toISOString() };

    // Cáº­p nháº­t sá»‘ tiá»n
    let newAmount = currentInvoice.amount;
    let newDiscount = currentInvoice.discount_amount;

    if (amount !== undefined) {
      newAmount = parseFloat(amount);
      updateData.amount = newAmount;
    }
    if (discount_amount !== undefined) {
      newDiscount = parseFloat(discount_amount);
      updateData.discount_amount = newDiscount;
    }

    // TÃ­nh láº¡i final_amount
    if (amount !== undefined || discount_amount !== undefined) {
      const newFinal = newAmount - newDiscount;
      updateData.final_amount = newFinal;

      // Cáº­p nháº­t status náº¿u cáº§n
      const paidAmount = currentInvoice.paid_amount || 0;
      if (paidAmount >= newFinal) {
        updateData.status = 'paid';
        updateData.paid_at = new Date().toISOString();
      } else if (paidAmount > 0) {
        updateData.status = 'partial';
      } else {
        updateData.status = 'unpaid';
      }
    }

    if (due_date !== undefined) updateData.due_date = due_date;
    if (description !== undefined) updateData.description = description;
    if (invoice_type !== undefined) updateData.invoice_type = invoice_type;

    const { data, error } = await supabase
      .from('invoices')
      .update(updateData)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;

    res.json({
      success: true,
      message: 'Cáº­p nháº­t hÃ³a Ä‘Æ¡n thÃ nh cÃ´ng',
      data
    });

  } catch (error) {
    console.error('Error updating invoice:', error);
    next(error);
  }
});

