/**
 * GET /api/holidays/check
 * Check if a specific date is a holiday
 * Query: ?date=2026-02-01
 * ðŸ”“ Authenticated users
 */
app.get('/api/holidays/check',
  requireAuth,
  async (req, res, next) => {
    try {
      const { date } = req.query;

      if (!date) {
        return res.status(400).json({
          success: false,
          message: 'NgÃ y lÃ  báº¯t buá»™c'
        });
      }

      // Check exact date match
      const { data: exactMatch, error: exactError } = await supabase
        .from('holidays')
        .select('id, name, date, description')
        .eq('date', date)
        .maybeSingle();

      if (exactError) throw exactError;

      if (exactMatch) {
        return res.json({
          success: true,
          isHoliday: true,
          holiday: exactMatch
        });
      }

      // Check recurring holidays (same month/day, any year)
      const checkDate = new Date(date);
      const month = checkDate.getMonth() + 1;
      const day = checkDate.getDate();

      const { data: recurring, error: recurringError } = await supabase
        .from('holidays')
        .select('id, name, date, description')
        .eq('is_recurring', true);

      if (recurringError) throw recurringError;

      const matchingRecurring = (recurring || []).find(h => {
        const hDate = new Date(h.date);
        return hDate.getMonth() + 1 === month && hDate.getDate() === day;
      });

      if (matchingRecurring) {
        return res.json({
          success: true,
          isHoliday: true,
          holiday: matchingRecurring,
          isRecurring: true
        });
      }

      res.json({
        success: true,
        isHoliday: false
      });
    } catch (error) {
      console.error('âŒ Error checking holiday:', error);
      next(error);
    }
  }
);

