/**
 * POST /api/admin/grades/override
 * Admin override grades (bypasses lock)
 * Body: { classId, gradeStructureId, grades: [...], override_reason }
 * ðŸ”’ SUPER_ADMIN, CENTER_MANAGER only
 */
app.post('/api/admin/grades/override', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const userId = req.user.id;
    const { classId, gradeStructureId, grades, override_reason } = req.body;

    console.log(`âš ï¸ Admin override grades: class ${classId}, structure ${gradeStructureId}`);

    // Validate
    if (!classId || !gradeStructureId) {
      return res.status(400).json({ success: false, message: 'Thiáº¿u classId hoáº·c gradeStructureId' });
    }
    if (!override_reason || override_reason.length < 10) {
      return res.status(400).json({ success: false, message: 'LÃ½ do override pháº£i cÃ³ Ã­t nháº¥t 10 kÃ½ tá»±' });
    }
    if (!grades || !Array.isArray(grades) || grades.length === 0) {
      return res.status(400).json({ success: false, message: 'Thiáº¿u danh sÃ¡ch Ä‘iá»ƒm' });
    }

    // Get old values for audit
    const { data: oldGrades } = await supabase
      .from('grades')
      .select('*')
      .eq('grade_structure_id', gradeStructureId)
      .in('enrollment_id', grades.map(g => g.enrollment_id));

    // Upsert grades with override info
    const upsertData = grades.map(g => ({
      enrollment_id: g.enrollment_id,
      grade_structure_id: gradeStructureId,
      score: g.score !== undefined && g.score !== '' ? parseFloat(g.score) : null,
      notes: g.notes || null,
      graded_by: userId,
      graded_at: new Date().toISOString(),
      override_reason: override_reason,
      overridden_by: userId,
      overridden_at: new Date().toISOString()
    }));

    const { data: savedGrades, error: saveError } = await supabase
      .from('grades')
      .upsert(upsertData, {
        onConflict: 'enrollment_id,grade_structure_id',
        ignoreDuplicates: false
      })
      .select();

    if (saveError) throw saveError;

    // Log to audit
    await supabase.from('grade_audit').insert({
      class_id: classId,
      grade_structure_id: gradeStructureId,
      action: 'overridden',
      changed_by: userId,
      reason: override_reason,
      old_values: { grades: oldGrades },
      new_values: { grades: savedGrades }
    });

    console.log(`âœ… Admin overrode ${savedGrades?.length || 0} grades`);

    res.json({
      success: true,
      message: `ÄÃ£ override ${savedGrades?.length || 0} Ä‘iá»ƒm thÃ nh cÃ´ng`,
      data: savedGrades
    });
  } catch (error) {
    console.error('âŒ Error overriding grades:', error);
    next(error);
  }
});

/**
 * GET /api/teacher/profile - ThÃ´ng tin profile cá»§a giÃ¡o viÃªn
 */
app.get('/api/teacher/profile', requireAuth, async (req, res, next) => {
  try {
    const teacherId = req.user.id;

    const { data: profile, error } = await supabase
      .from('users')
      .select(`
        id,
        email,
        full_name,
        phone,
        avatar_url,
        hourly_rate,
        status,
        created_at,
        center_id,
        centers (id, name, address, hotline),
        roles (id, code, name)
      `)
      .eq('id', teacherId)
      .single();

    if (error) throw error;

    // Get teaching stats
    const now = new Date();
    const currentYear = now.getFullYear();

    // Total classes taught
    const { count: totalClasses } = await supabase
      .from('classes')
      .select('id', { count: 'exact', head: true })
      .eq('teacher_id', teacherId);

    // Total sessions completed
    const { count: totalSessions } = await supabase
      .from('sessions')
      .select('id', { count: 'exact', head: true })
      .eq('teacher_id', teacherId)
      .eq('status', 'completed');

    // Total hours this year
    const { data: yearSessions } = await supabase
      .from('sessions')
      .select('duration_hours')
      .eq('teacher_id', teacherId)
      .eq('status', 'completed')
      .gte('session_date', `${currentYear}-01-01`);

    const totalHoursThisYear = yearSessions?.reduce((sum, s) => sum + (parseFloat(s.duration_hours) || 0), 0) || 0;

    res.json({
      success: true,
      data: {
        ...profile,
        stats: {
          totalClasses: totalClasses || 0,
          totalSessions: totalSessions || 0,
          totalHoursThisYear: Math.round(totalHoursThisYear * 10) / 10
        }
      }
    });
  } catch (error) {
    console.error('Error fetching teacher profile:', error);
    next(error);
  }
});

/**
 * PUT /api/teacher/profile - Cập nhật thông tin cá nhân (phone, avatar_url)
 * 🔒 Authenticated teacher only — whitelist fields
 */
app.put('/api/teacher/profile', requireAuth, async (req, res, next) => {
  try {
    const teacherId = req.user.id;
    const { phone, avatar_url } = req.body;

    console.log(`✏️ Teacher ${req.user.email} updating profile`);

    // Whitelist: only allow these fields
    const updates = {};
    if (phone !== undefined) {
      const phoneClean = phone ? phone.replace(/\s/g, '') : '';
      if (phoneClean && !/^0\d{9}$/.test(phoneClean)) {
        return res.status(400).json({
          success: false,
          message: 'Số điện thoại không hợp lệ (10 số, bắt đầu bằng 0)'
        });
      }
      updates.phone = phoneClean || null;
    }
    if (avatar_url !== undefined) {
      updates.avatar_url = avatar_url || null;
    }

    if (Object.keys(updates).length === 0) {
      return res.status(400).json({
        success: false,
        message: 'Không có thông tin nào để cập nhật'
      });
    }

    updates.updated_at = new Date().toISOString();

    const { data, error } = await supabase
      .from('users')
      .update(updates)
      .eq('id', teacherId)
      .select('id, email, full_name, phone, avatar_url, hourly_rate, status, created_at')
      .single();

    if (error) throw error;

    res.json({
      success: true,
      data,
      message: 'Cập nhật hồ sơ thành công'
    });
  } catch (error) {
    console.error('Error updating teacher profile:', error);
    next(error);
  }
});

/**
 * GET /api/teacher/schedule - Láº¥y lá»‹ch dáº¡y cá»§a giÃ¡o viÃªn theo khoáº£ng thá»i gian
 * Query params: start_date, end_date (default: this week)
 */
app.get('/api/teacher/schedule', requireAuth, async (req, res, next) => {
  try {
    const teacherId = req.user.id;

    // Default to this week
    const now = new Date();
    const dayOfWeek = now.getDay();
    const monday = new Date(now);
    monday.setDate(now.getDate() - (dayOfWeek === 0 ? 6 : dayOfWeek - 1));
    const sunday = new Date(monday);
    sunday.setDate(monday.getDate() + 6);

    const startDate = req.query.start_date || monday.toISOString().split('T')[0];
    const endDate = req.query.end_date || sunday.toISOString().split('T')[0];

    const { data: sessions, error } = await supabase
      .from('sessions')
      .select(`
        id,
        session_number,
        session_date,
        start_time,
        end_time,
        duration_hours,
        status,
        topic,
        notes,
        room_id,
        is_locked,
        classes (
          id,
          code,
          name,
          rooms (id, name, capacity),
          courses (id, code, title),
          centers (id, name)
        )
      `)
      .eq('teacher_id', teacherId)
      .gte('session_date', startDate)
      .lte('session_date', endDate)
      .order('session_date', { ascending: true })
      .order('start_time', { ascending: true });

    if (error) throw error;

    // Group by date for easier rendering
    const groupedByDate = {};
    sessions?.forEach(session => {
      const date = session.session_date;
      if (!groupedByDate[date]) {
        groupedByDate[date] = [];
      }
      groupedByDate[date].push({
        ...session,
        class_name: session.classes?.name,
        class_code: session.classes?.code,
        course_name: session.classes?.courses?.title,
        room_name: session.classes?.rooms?.name,
        center_name: session.classes?.centers?.name
      });
    });

    // Generate all dates in range
    const allDates = [];
    const current = new Date(startDate);
    const end = new Date(endDate);
    while (current <= end) {
      const dateStr = current.toISOString().split('T')[0];
      allDates.push({
        date: dateStr,
        dayOfWeek: current.getDay(),
        sessions: groupedByDate[dateStr] || []
      });
      current.setDate(current.getDate() + 1);
    }

    // Stats
    const totalSessions = sessions?.length || 0;
    const completedSessions = sessions?.filter(s => s.status === 'completed').length || 0;
    const totalHours = sessions?.reduce((sum, s) => sum + (parseFloat(s.duration_hours) || 0), 0) || 0;

    res.json({
      success: true,
      data: {
        startDate,
        endDate,
        schedule: allDates,
        stats: {
          totalSessions,
          completedSessions,
          totalHours: Math.round(totalHours * 10) / 10
        }
      }
    });
  } catch (error) {
    console.error('Error fetching teacher schedule:', error);
    next(error);
  }
});

/**
 * GET /api/teacher/schedule/month - Láº¥y lá»‹ch dáº¡y theo thÃ¡ng (cho calendar view)
 * Query params: month, year
 */
app.get('/api/teacher/schedule/month', requireAuth, async (req, res, next) => {
  try {
    const teacherId = req.user.id;
    const now = new Date();
    const month = parseInt(req.query.month) || (now.getMonth() + 1);
    const year = parseInt(req.query.year) || now.getFullYear();

    const firstDay = `${year}-${String(month).padStart(2, '0')}-01`;
    const lastDay = new Date(year, month, 0).toISOString().split('T')[0];

    const { data: sessions, error } = await supabase
      .from('sessions')
      .select(`
        id,
        session_number,
        session_date,
        start_time,
        end_time,
        duration_hours,
        status,
        classes (
          id,
          code,
          name,
          courses (id, title)
        )
      `)
      .eq('teacher_id', teacherId)
      .gte('session_date', firstDay)
      .lte('session_date', lastDay)
      .order('session_date')
      .order('start_time');

    if (error) throw error;

    // Group sessions by date
    const sessionsByDate = {};
    sessions?.forEach(session => {
      const date = session.session_date;
      if (!sessionsByDate[date]) {
        sessionsByDate[date] = [];
      }
      sessionsByDate[date].push({
        id: session.id,
        start_time: session.start_time,
        end_time: session.end_time,
        status: session.status,
        class_name: session.classes?.name,
        class_code: session.classes?.code,
        course_title: session.classes?.courses?.title
      });
    });

    res.json({
      success: true,
      data: {
        month,
        year,
        sessionsByDate,
        totalSessions: sessions?.length || 0
      }
    });
  } catch (error) {
    console.error('Error fetching teacher monthly schedule:', error);
    next(error);
  }
});

