// NOTIFICATION BELL APIs (fetch, mark read)
// ============================================================

/**
 * GET /api/notifications
 * Fetch notifications for the authenticated user (paginated)
 */
app.get('/api/notifications', requireAuth, async (req, res, next) => {
  try {
    const userId = req.user.id;
    const { effectiveCenterId } = getEffectiveCenterId(req.user);
    const { unread, limit = 20, offset = 0 } = req.query;
    const limitNum = Math.min(parseInt(limit) || 20, 50);
    const offsetNum = parseInt(offset) || 0;

    let query = supabase
      .from('notifications')
      .select('id, type, title, message, reference_id, reference_type, read_at, created_at', { count: 'exact' })
      .eq('user_id', userId);
    
    // Only filter by center if effectiveCenterId is set (CENTER_MANAGER or SUPER_ADMIN with specific center)
    if (effectiveCenterId) {
      query = query.eq('center_id', effectiveCenterId);
    }
    
    query = query
      .order('created_at', { ascending: false })
      .range(offsetNum, offsetNum + limitNum - 1);

    if (unread === 'true') {
      query = query.is('read_at', null);
    }

    const { data, error, count } = await query;
    if (error) throw error;

    // Get unread count separately
    let unreadQuery = supabase
      .from('notifications')
      .select('id', { count: 'exact', head: true })
      .eq('user_id', userId);
    
    if (effectiveCenterId) {
      unreadQuery = unreadQuery.eq('center_id', effectiveCenterId);
    }
    unreadQuery = unreadQuery.is('read_at', null);

    const { count: unreadCount, error: unreadError } = await unreadQuery;

    if (unreadError) throw unreadError;

    res.json({
      success: true,
      data: {
        notifications: data || [],
        total: count || 0,
        unreadCount: unreadCount || 0
      }
    });
  } catch (error) {
    console.error('Error fetching notifications:', error);
    next(error);
  }
});

/**
 * PATCH /api/notifications/read-all
 * Mark all unread notifications as read (must be before :id route)
 */
app.patch('/api/notifications/read-all', requireAuth, async (req, res, next) => {
  try {
    const userId = req.user.id;
    const { effectiveCenterId } = getEffectiveCenterId(req.user);

    let updateQuery = supabase
      .from('notifications')
      .update({ read_at: new Date().toISOString() })
      .eq('user_id', userId);
    
    if (effectiveCenterId) {
      updateQuery = updateQuery.eq('center_id', effectiveCenterId);
    }
    updateQuery = updateQuery.is('read_at', null);

    const { data, error } = await updateQuery
      .select('id');

    if (error) throw error;

    res.json({
      success: true,
      data: { updated: data?.length || 0 }
    });
  } catch (error) {
    console.error('Error marking all notifications as read:', error);
    next(error);
  }
});

/**
 * PATCH /api/notifications/:id/read
 * Mark a single notification as read
 */
app.patch('/api/notifications/:id/read', requireAuth, async (req, res, next) => {
  try {
    const userId = req.user.id;
    const { id } = req.params;

    const { data, error } = await supabase
      .from('notifications')
      .update({ read_at: new Date().toISOString() })
      .eq('id', id)
      .eq('user_id', userId)
      .select('id, read_at')
      .single();

    if (error) {
      if (error.code === 'PGRST116') {
        return res.status(404).json({ success: false, message: 'Notification not found' });
      }
      throw error;
    }

    res.json({ success: true, data });
  } catch (error) {
    console.error('Error marking notification as read:', error);
    next(error);
  }
});

