/**
 * GET /api/admin/support-tickets
 * Láº¥y danh sÃ¡ch support tickets vá»›i filters
 */
app.get('/api/admin/support-tickets', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER', 'TEACHER']), async (req, res, next) => {
  try {
    const { status, priority, category, center_id: queryCenterId, search, page = 1, limit = 50 } = req.query;

    // Permission check with center filtering
    const { effectiveCenterId, error: permError } = getEffectiveCenterId(req.user, queryCenterId);
    if (permError) {
      return res.status(403).json({ success: false, message: permError });
    }

    // Build query
    let query = supabase
      .from('support_tickets')
      .select(`
        *,
        created_by_user:users!support_tickets_created_by_fkey (id, full_name, email, phone),
        assigned_to_user:users!support_tickets_assigned_to_fkey (id, full_name, email),
        classes!support_tickets_class_id_fkey (id, name),
        enrollments!support_tickets_enrollment_id_fkey (id)
      `)
      .order('created_at', { ascending: false });

    // Apply filters
    if (effectiveCenterId) {
      query = query.eq('center_id', effectiveCenterId);
    }

    if (status) {
      query = query.eq('status', status);
    }

    if (priority) {
      query = query.eq('priority', priority);
    }

    if (category) {
      query = query.eq('category', category);
    }

    // Search by ticket number or subject
    if (search && search.trim().length >= 2) {
      const term = search.trim();
      query = query.or(`ticket_number.ilike.%${term}%,subject.ilike.%${term}%`);
    }

    // Pagination
    const pageNum = parseInt(page) || 1;
    const limitNum = Math.min(parseInt(limit) || 50, 100);
    const offset = (pageNum - 1) * limitNum;
    query = query.range(offset, offset + limitNum - 1);

    const { data, error, count } = await query;

    if (error) throw error;

    // Get message counts for each ticket
    const ticketIds = (data || []).map(t => t.id);
    let messageCounts = {};

    if (ticketIds.length > 0) {
      const { data: msgData } = await supabase
        .from('ticket_messages')
        .select('ticket_id')
        .in('ticket_id', ticketIds);

      if (msgData) {
        msgData.forEach(m => {
          messageCounts[m.ticket_id] = (messageCounts[m.ticket_id] || 0) + 1;
        });
      }
    }

    // Transform data for frontend compatibility
    const transformedData = (data || []).map(ticket => ({
      ...ticket,
      students: ticket.created_by_user || null, // Frontend expects 'students' key
      assigned_to: ticket.assigned_to_user || null,
      message_count: messageCounts[ticket.id] || 0
    }));

    console.log(`ðŸŽ« Support tickets fetched: ${transformedData.length} items by ${req.user.email}`);

    res.json({
      success: true,
      data: transformedData,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: count || transformedData.length
      }
    });
  } catch (error) {
    console.error('âŒ Error fetching support tickets:', error);
    next(error);
  }
});

/**
 * GET /api/admin/support-tickets/:id
 * Láº¥y chi tiáº¿t ticket kÃ¨m messages
 */
app.get('/api/admin/support-tickets/:id', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER', 'TEACHER']), async (req, res, next) => {
  try {
    const { id } = req.params;

    // Get ticket
    const { data: ticket, error: ticketError } = await supabase
      .from('support_tickets')
      .select(`
        *,
        created_by_user:users!support_tickets_created_by_fkey (id, full_name, email, phone),
        assigned_to_user:users!support_tickets_assigned_to_fkey (id, full_name, email),
        resolved_by_user:users!support_tickets_resolved_by_fkey (id, full_name),
        classes!support_tickets_class_id_fkey (id, name)
      `)
      .eq('id', id)
      .single();

    if (ticketError) {
      if (ticketError.code === 'PGRST116') {
        return res.status(404).json({ success: false, message: 'Ticket khÃ´ng tá»“n táº¡i' });
      }
      throw ticketError;
    }

    // Permission check
    if (req.user.roleCode !== 'SUPER_ADMIN' && ticket.center_id && ticket.center_id !== req.user.centerId) {
      return res.status(403).json({ success: false, message: 'Báº¡n khÃ´ng cÃ³ quyá»n xem ticket nÃ y' });
    }

    // Get messages
    let messagesQuery = supabase
      .from('ticket_messages')
      .select(`
        *,
        sender:users!ticket_messages_sender_id_fkey (id, full_name, email, roles!users_role_id_fkey (code))
      `)
      .eq('ticket_id', id)
      .order('created_at', { ascending: true });

    // If user is student (ticket creator), hide internal messages
    if (req.user.id === ticket.created_by && req.user.roleCode === 'STUDENT') {
      messagesQuery = messagesQuery.eq('is_internal', false);
    }

    const { data: messages, error: msgError } = await messagesQuery;

    if (msgError) throw msgError;

    // Enrich with consultation context if this is a follow-up ticket
    let consultation_context = null;
    if (ticket.consultation_request_id) {
      try {
        const { data: cr } = await supabase
          .from('consultation_requests')
          .select('id, full_name, phone, email, preferred_time, notes, status, metadata, transcript_summary, source, session_id, created_at')
          .eq('id', ticket.consultation_request_id)
          .single();

        if (cr) {
          const meta = cr.metadata || {};
          let chatExcerpt = [];

          if (cr.session_id) {
            const { data: chatMsgs } = await supabase
              .from('chat_messages')
              .select('id, role, content, created_at')
              .eq('session_id', cr.session_id)
              .neq('role', 'system')
              .order('created_at', { ascending: false })
              .limit(5);
            chatExcerpt = (chatMsgs || []).reverse();
          }

          consultation_context = {
            id: cr.id,
            full_name: cr.full_name,
            phone: cr.phone,
            email: cr.email,
            preferred_time: cr.preferred_time,
            status: cr.status,
            source: cr.source,
            advisor_notes: cr.notes,
            transcript_summary: cr.transcript_summary,
            created_at: cr.created_at,
            intake: {
              goal: meta.goal || null,
              level: meta.level || null,
              course: meta.course || null,
              message: meta.message || null,
            },
            chat_excerpt: chatExcerpt,
          };
        }
      } catch (ctxErr) {
        console.warn('âš ï¸ Could not load consultation context:', ctxErr.message);
      }
    }

    res.json({
      success: true,
      data: {
        ...ticket,
        students: ticket.created_by_user || null,
        assigned_to: ticket.assigned_to_user || null,
        resolved_by: ticket.resolved_by_user || null,
        messages: messages || [],
        consultation_context
      }
    });
  } catch (error) {
    console.error('âŒ Error fetching support ticket:', error);
    next(error);
  }
});

/**
 * POST /api/support-tickets
 * Student/self-service ticket creation (authoritative route)
 */
app.post('/api/support-tickets', requireAuth, async (req, res, next) => {
  try {
    const {
      subject,
      message,
      description,
      category = 'general',
      priority = 'normal',
      class_id,
      enrollment_id
    } = req.body;

    if (!subject || !String(subject).trim()) {
      return res.status(400).json({ success: false, message: 'TiÃªu Ä‘á» lÃ  báº¯t buá»™c' });
    }

    const normalizedCategory = {
      academic: 'course',
      financial: 'billing',
      technical: 'technical',
      other: 'other',
      general: 'general',
      billing: 'billing',
      course: 'course'
    }[category] || 'general';

    const normalizedPriority = {
      medium: 'normal',
      low: 'low',
      normal: 'normal',
      high: 'high',
      urgent: 'urgent'
    }[priority] || 'normal';

    const validCategories = ['general', 'technical', 'billing', 'course', 'other'];
    if (!validCategories.includes(normalizedCategory)) {
      return res.status(400).json({ success: false, message: 'Danh má»¥c khÃ´ng há»£p lá»‡' });
    }

    const validPriorities = ['low', 'normal', 'high', 'urgent'];
    if (!validPriorities.includes(normalizedPriority)) {
      return res.status(400).json({ success: false, message: 'Äá»™ Æ°u tiÃªn khÃ´ng há»£p lá»‡' });
    }

    const { effectiveCenterId } = getEffectiveCenterId(req.user, req.body.center_id);

    const { data: ticketNumber, error: numberError } = await supabase.rpc('generate_ticket_number');
    if (numberError) throw numberError;

    const { data: createdTicket, error: createError } = await supabase
      .from('support_tickets')
      .insert({
        ticket_number: ticketNumber,
        subject: String(subject).trim(),
        category: normalizedCategory,
        priority: normalizedPriority,
        status: 'open',
        created_by: req.user.id,
        assigned_to: null,
        center_id: effectiveCenterId || req.user.centerId || null,
        class_id: class_id || null,
        enrollment_id: enrollment_id || null
      })
      .select('*')
      .single();

    if (createError) throw createError;

    const initialMessage = (message || description || '').trim();
    if (initialMessage) {
      const { error: messageError } = await supabase
        .from('ticket_messages')
        .insert({
          ticket_id: createdTicket.id,
          message: initialMessage,
          sender_id: req.user.id,
          is_internal: false
        });

      if (messageError) throw messageError;
    }

    res.status(201).json({
      success: true,
      message: 'ÄÃ£ táº¡o yÃªu cáº§u há»— trá»£',
      data: {
        ...createdTicket,
        message_count: initialMessage ? 1 : 0
      }
    });
  } catch (error) {
    console.error('âŒ Error creating support ticket for self-service route:', error);
    next(error);
  }
});

