// ============================================================
// STUDENT PORTAL APIs
// ============================================================

/**
 * GET /api/student/dashboard
 * Get student dashboard overview
 * Returns: today's classes, recent grades, upcoming payments, notifications
 * ðŸ”’ STUDENT only (uses req.user.id)
 */
app.get('/api/student/dashboard',
  requireAuth,
  requireRole(['STUDENT']),
  async (req, res, next) => {
    try {
      const studentId = req.user.id;
      const vnDateParts = new Intl.DateTimeFormat('en-US', {
        timeZone: 'Asia/Ho_Chi_Minh',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      })
        .formatToParts(new Date())
        .reduce((acc, part) => {
          if (part.type !== 'literal') {
            acc[part.type] = part.value;
          }
          return acc;
        }, {});
      const todayDateInVN = `${vnDateParts.year}-${vnDateParts.month}-${vnDateParts.day}`;

      // 1. Get enrolled classes
      const { data: enrollments } = await supabase
        .from('enrollments')
        .select(`
          id, status,
          class:classes(
            id, name, code, schedule, start_date, end_date, room,
            course:courses(id, title),
            teacher:users!classes_teacher_id_fkey(id, full_name)
          )
        `)
        .eq('student_id', studentId)
        .eq('status', 'active');

      // 2. Build today's classes from sessions (single source of truth with schedule page)
      const activeClassIds = (enrollments || []).map(e => e.class?.id).filter(Boolean);
      let todayClasses = [];
      let nextClass = null;

      const mapSessionToClassItem = (session) => ({
        id: session.id,
        class_id: session.class_id,
        class_name: session.class?.name,
        class_code: session.class?.code,
        name: session.class?.name,
        course_name: session.class?.course?.title,
        teacher_name: session.class?.teacher?.full_name,
        session_date: session.session_date,
        start_time: session.start_time,
        end_time: session.end_time,
        room_name: session.class?.room || null,
        status: session.status || 'scheduled'
      });

      if (activeClassIds.length > 0) {
        const { data: todaySessions, error: todaySessionsError } = await supabase
          .from('sessions')
          .select(`
            id,
            class_id,
            session_date,
            start_time,
            end_time,
            status,
            class:classes(
              id, name, code, room,
              course:courses(id, title),
              teacher:users!classes_teacher_id_fkey(id, full_name)
            )
          `)
          .in('class_id', activeClassIds)
          .eq('session_date', todayDateInVN)
          .order('start_time', { ascending: true });

        if (todaySessionsError) throw todaySessionsError;

        todayClasses = (todaySessions || [])
          .filter((session) => String(session.status || '').toLowerCase() !== 'cancelled')
          .map(mapSessionToClassItem);

        const { data: upcomingSessions, error: upcomingSessionsError } = await supabase
          .from('sessions')
          .select(`
            id,
            class_id,
            session_date,
            start_time,
            end_time,
            status,
            class:classes(
              id, name, code, room,
              course:courses(id, title),
              teacher:users!classes_teacher_id_fkey(id, full_name)
            )
          `)
          .in('class_id', activeClassIds)
          .gte('session_date', todayDateInVN)
          .order('session_date', { ascending: true })
          .order('start_time', { ascending: true })
          .limit(10);

        if (upcomingSessionsError) throw upcomingSessionsError;

        const firstUpcoming = (upcomingSessions || []).find((session) => {
          const normalizedStatus = String(session.status || '').toLowerCase();
          return normalizedStatus !== 'cancelled' && normalizedStatus !== 'completed';
        });

        if (firstUpcoming) {
          nextClass = mapSessionToClassItem(firstUpcoming);
        }
      }

      // 3. Get recent grades (last 5) - via enrollments
      const { data: recentGrades } = await supabase
        .from('grades')
        .select(`
          id, score, created_at, notes,
          grade_structure:grade_structures(id, name, weight),
          enrollment:enrollments!inner(
            id, student_id,
            class:classes(id, name, code)
          )
        `)
        .eq('enrollment.student_id', studentId)
        .order('created_at', { ascending: false })
        .limit(5);
      
      // Transform grades to expected format
      const formattedRecentGrades = (recentGrades || []).map(g => ({
        id: g.id,
        score: g.score,
        grade_type: g.grade_structure?.name,
        created_at: g.created_at,
        notes: g.notes,
        class: g.enrollment?.class
      }));

      const activeEnrollmentIds = (enrollments || []).map(enrollment => enrollment.id).filter(Boolean);

      // 4. Get all outstanding invoices for accurate unpaid amount
      const outstandingStatuses = ['unpaid', 'partial', 'overdue', 'pending'];
      const { data: allOutstandingInvoices, error: outstandingInvoicesError } = await supabase
        .from('invoices')
        .select('id, invoice_code, final_amount, paid_amount, due_date, status')
        .eq('student_id', studentId)
        .in('status', outstandingStatuses)
        .order('due_date', { ascending: true });

      if (outstandingInvoicesError) throw outstandingInvoicesError;

      const unpaidInvoices = (allOutstandingInvoices || []).slice(0, 3);

      const unpaidAmount = (allOutstandingInvoices || []).reduce((sum, invoice) => {
        const finalAmount = Number(invoice.final_amount) || 0;
        const paidAmount = Number(invoice.paid_amount) || 0;
        const remaining = Math.max(0, finalAmount - paidAmount);
        return sum + remaining;
      }, 0);

      // 5. Get attendance rate
      // NOTE: attendance schema differs between deployments:
      // - some have `student_id`
      // - some only have `enrollment_id`
      // We query both paths with graceful fallback when a column doesn't exist (42703).
      let attendanceByStudentData = [];
      const attendanceByStudentRes = await supabase
        .from('attendance')
        .select('id, status')
        .eq('student_id', studentId);

      if (attendanceByStudentRes.error) {
        if (attendanceByStudentRes.error.code !== '42703') {
          throw attendanceByStudentRes.error;
        }
      } else {
        attendanceByStudentData = attendanceByStudentRes.data || [];
      }

      let attendanceByEnrollmentData = [];
      if (activeEnrollmentIds.length > 0) {
        const attendanceByEnrollmentRes = await supabase
          .from('attendance')
          .select('id, status')
          .in('enrollment_id', activeEnrollmentIds);

        if (attendanceByEnrollmentRes.error) {
          if (attendanceByEnrollmentRes.error.code !== '42703') {
            throw attendanceByEnrollmentRes.error;
          }
        } else {
          attendanceByEnrollmentData = attendanceByEnrollmentRes.data || [];
        }
      }

      const attendanceMap = new Map();
      for (const attendance of attendanceByStudentData) {
        attendanceMap.set(attendance.id, attendance);
      }
      for (const attendance of attendanceByEnrollmentData) {
        attendanceMap.set(attendance.id, attendance);
      }
      const attendanceStats = Array.from(attendanceMap.values());

      const totalSessions = attendanceStats?.length || 0;
      const presentSessions = attendanceStats?.filter(a => a.status === 'present' || a.status === 'late').length || 0;
      const attendanceRate = totalSessions > 0 ? Math.round((presentSessions / totalSessions) * 100) : 0;

      // 6. Calculate average grade - via enrollments
      const { data: allGrades } = await supabase
        .from('grades')
        .select('score, enrollment:enrollments!inner(student_id)')
        .eq('enrollment.student_id', studentId);

      const avgGrade = allGrades?.length > 0
        ? (allGrades.reduce((sum, g) => sum + (g.score || 0), 0) / allGrades.length).toFixed(1)
        : null;

      console.log(`ðŸ“Š Student dashboard loaded for ${studentId}`);

      res.json({
        success: true,
        data: {
          activeEnrollmentCount: enrollments?.length || 0,
          todayClasses,
          nextClass,
          recentGrades: formattedRecentGrades,
          unpaidInvoices: unpaidInvoices || [],
          stats: {
            totalClasses: enrollments?.length || 0,
            attendanceRate,
            avgGrade,
            unpaidAmount
          }
        }
      });
    } catch (error) {
      console.error('âŒ Error fetching student dashboard:', error);
      next(error);
    }
  }
);

/**
 * GET /api/student/schedule
 * Get student's class schedule
 * Query: ?view=week|month&date=2026-01-10&classId=xxx
 * ðŸ”’ STUDENT only
 */
app.get('/api/student/schedule',
  requireAuth,
  requireRole(['STUDENT']),
  async (req, res, next) => {
    try {
      const studentId = req.user.id;
      const { view = 'week', startDate, endDate, classId, enrollmentScope = 'active' } = req.query;

      const enrollmentStatuses = enrollmentScope === 'all_enrolled'
        ? ['active', 'completed', 'pending']
        : ['active'];

      // 1. Get enrolled classes (for filter list and permission check)
      let enrollmentQuery = supabase
        .from('enrollments')
        .select(`
          class:classes(
            id, name, code
          )
        `)
        .eq('student_id', studentId);

      enrollmentQuery = enrollmentStatuses.length === 1
        ? enrollmentQuery.eq('status', enrollmentStatuses[0])
        : enrollmentQuery.in('status', enrollmentStatuses);

      const { data: enrollments, error: enrollError } = await enrollmentQuery;

      if (enrollError) throw enrollError;

      const enrolledClassIds = enrollments?.map(e => e.class?.id).filter(Boolean) || [];

      if (enrolledClassIds.length === 0) {
        return res.json({
          success: true,
          data: {
            sessions: [],
            classes: [],
            statistics: {
              totalSessions: 0,
              completedSessions: 0,
              upcomingSessions: 0
            }
          }
        });
      }

      // 2. Query sessions based on enrolled classes and date range
      let query = supabase
        .from('sessions')
        .select(`
          id,
          session_date,
          start_time,
          end_time,
          status,
          session_number,
          class:classes(
            id, name, code, room,
            course:courses(id, title),
            teacher:users!classes_teacher_id_fkey(id, full_name)
          )
        `)
        .in('class_id', enrolledClassIds)
        .order('session_date', { ascending: true })
        .order('start_time', { ascending: true });

      // Apply filters
      if (classId) {
        query = query.eq('class_id', classId);
      }
      
      if (startDate) {
        query = query.gte('session_date', startDate);
      }
      
      if (endDate) {
        query = query.lte('session_date', endDate);
      }

      const { data: sessionsData, error: sessionError } = await query;
      if (sessionError) throw sessionError;

      // 3. Transform data for frontend
      const sessions = (sessionsData || []).map(session => {
        const date = new Date(session.session_date);
        // JS getDay(): 0=Sun, 1=Mon... We want 8=Sun, 2=Mon...
        // 0 (Sun) -> 8
        // 1 (Mon) -> 2
        // ...
        const jsDay = date.getDay();
        const dayOfWeek = jsDay === 0 ? 8 : jsDay + 1;

        return {
          sessionId: session.id,
          classId: session.class?.id,
          className: session.class?.name,
          classCode: session.class?.code,
          courseName: session.class?.course?.title,
          courseId: session.class?.course?.id,
          teacherName: session.class?.teacher?.full_name,
          roomName: session.class?.room || null,
          sessionDate: session.session_date,
          dayOfWeek: dayOfWeek,
          startTime: session.start_time,
          endTime: session.end_time,
          status: session.status || 'scheduled',
          sessionNumber: session.session_number
        };
      });

      // 4. Calculate statistics
      const now = new Date();
      const stats = {
        totalSessions: sessions.length,
        completedSessions: sessions.filter(s => s.status === 'completed' || new Date(s.sessionDate + ' ' + s.endTime) < now).length,
        upcomingSessions: sessions.filter(s => s.status === 'scheduled' && new Date(s.sessionDate + ' ' + s.startTime) > now).length
      };

      // 5. Unique classes list for filter dropdown
      const uniqueClasses = Array.from(
        new Map(
          (enrollments || [])
            .map((e) => e?.class)
            .filter(Boolean)
            .map((cls) => [cls.id, cls])
        ).values()
      );

      console.log(`ðŸ“… Fetched ${sessions.length} sessions for student ${studentId}`);

      res.json({
        success: true,
        data: {
          sessions,
          classes: uniqueClasses,
          statistics: stats
        }
      });
    } catch (error) {
      console.error('âŒ Error fetching student schedule:', error);
      next(error);
    }
  }
);

/**
 * GET /api/student/grades
 * Get all student grades with statistics
 * Query: ?classId=xxx
 * ðŸ”’ STUDENT only
 */
app.get('/api/student/grades',
  requireAuth,
  requireRole(['STUDENT']),
  async (req, res, next) => {
    try {
      const studentId = req.user.id;
      const { classId } = req.query;

      // Query grades via enrollments (correct schema relationship)
      let query = supabase
        .from('grades')
        .select(`
          id, score, notes, created_at,
          grade_structure:grade_structures(id, name, weight, max_score),
          enrollment:enrollments!inner(
            id, student_id, class_id,
            class:classes(id, name, code, course:courses(id, title))
          )
        `)
        .eq('enrollment.student_id', studentId)
        .order('created_at', { ascending: false });

      if (classId) {
        query = query.eq('enrollment.class_id', classId);
      }

      const { data: rawGrades, error } = await query;
      if (error) throw error;

      // Transform to expected format
      const grades = (rawGrades || []).map(g => ({
        id: g.id,
        score: g.score,
        grade_type: g.grade_structure?.name,
        weight: g.grade_structure?.weight,
        max_score: g.grade_structure?.max_score,
        notes: g.notes,
        created_at: g.created_at,
        class: g.enrollment?.class
      }));

      // Calculate statistics per class
      const classStats = {};
      for (const grade of grades) {
        const cid = grade.class?.id;
        if (!cid) continue;

        if (!classStats[cid]) {
          classStats[cid] = {
            classId: cid,
            className: grade.class.name,
            classCode: grade.class.code,
            courseTitle: grade.class.course?.title,
            grades: [],
            totalScore: 0,
            totalWeight: 0
          };
        }
        classStats[cid].grades.push(grade);
        classStats[cid].totalScore += (grade.score || 0) * (grade.weight || 1);
        classStats[cid].totalWeight += (grade.weight || 1);
      }

      // Calculate weighted average per class
      const classSummaries = Object.values(classStats).map(cs => ({
        ...cs,
        avgScore: cs.totalWeight > 0 ? (cs.totalScore / cs.totalWeight).toFixed(2) : null,
        gradeCount: cs.grades.length
      }));

      // Overall statistics
      const allScores = grades.map(g => g.score).filter(s => s != null);
      const overallAvg = allScores.length > 0
        ? (allScores.reduce((a, b) => a + b, 0) / allScores.length).toFixed(2)
        : null;

      console.log(`ðŸ“ Student grades loaded: ${grades.length} grades`);

      res.json({
        success: true,
        data: {
          grades,
          classSummaries,
          statistics: {
            totalGrades: grades.length,
            overallAverage: overallAvg,
            highestScore: allScores.length > 0 ? Math.max(...allScores) : null,
            lowestScore: allScores.length > 0 ? Math.min(...allScores) : null
          }
        }
      });
    } catch (error) {
      console.error('âŒ Error fetching student grades:', error);
      next(error);
    }
  }
);

/**
 * GET /api/student/attendance
 * Get student attendance history
 * Query: ?classId=xxx&startDate=xxx&endDate=xxx
 * ðŸ”’ STUDENT only
 */
app.get('/api/student/attendance',
  requireAuth,
  requireRole(['STUDENT']),
  async (req, res, next) => {
    try {
      const studentId = req.user.id;
      const { classId, startDate, endDate } = req.query;

      // attendance table uses enrollment_id, not student_id directly
      // Schema: attendance.enrollment_id -> enrollments.id, enrollments.student_id -> users
      let query = supabase
        .from('attendance')
        .select(`
          id, status, notes, check_in_time, created_at,
          session:sessions(
            id, session_date, start_time, end_time,
            class:classes(id, name, code, course:courses(id, title))
          ),
          enrollment:enrollments!inner(
            id, student_id,
            class:classes(id, name, code)
          )
        `)
        .eq('enrollment.student_id', studentId)
        .order('created_at', { ascending: false });

      const { data: attendance, error } = await query;
      if (error) throw error;

      // Filter by class if specified (use enrollment's class_id or session's class_id)
      let filtered = attendance || [];
      if (classId) {
        filtered = filtered.filter(a => 
          a.session?.class?.id === classId || a.enrollment?.class?.id === classId
        );
      }

      // Filter by date range
      if (startDate) {
        filtered = filtered.filter(a => a.session?.session_date >= startDate);
      }
      if (endDate) {
        filtered = filtered.filter(a => a.session?.session_date <= endDate);
      }

      // Calculate statistics
      const total = filtered.length;
      const present = filtered.filter(a => a.status === 'present').length;
      const absent = filtered.filter(a => a.status === 'absent').length;
      const late = filtered.filter(a => a.status === 'late').length;
      const excused = filtered.filter(a => a.status === 'excused').length;

      // Group by class for per-class stats (use session's class OR enrollment's class as fallback)
      const classAttendance = {};
      for (const record of filtered) {
        const cid = record.session?.class?.id || record.enrollment?.class?.id;
        const cname = record.session?.class?.name || record.enrollment?.class?.name;
        const ccode = record.session?.class?.code || record.enrollment?.class?.code;
        if (!cid) continue;

        if (!classAttendance[cid]) {
          classAttendance[cid] = {
            classId: cid,
            className: cname,
            classCode: ccode,
            total: 0,
            present: 0,
            absent: 0,
            late: 0,
            excused: 0
          };
        }
        classAttendance[cid].total++;
        classAttendance[cid][record.status]++;
      }

      const classSummaries = Object.values(classAttendance).map(ca => ({
        ...ca,
        presentCount: ca.present,
        absentCount: ca.absent,
        lateCount: ca.late,
        excusedCount: ca.excused,
        totalSessions: ca.total,
        attendanceRate: ca.total > 0 ? Math.round(((ca.present + ca.late) / ca.total) * 100) : 0
      }));

      // Transform records for frontend (add class_id and class_name at top level)
      const transformedRecords = filtered.map(r => ({
        id: r.id,
        status: r.status,
        notes: r.notes,
        check_in_time: r.check_in_time,
        created_at: r.created_at,
        session_date: r.session?.session_date,
        class_id: r.session?.class?.id || r.enrollment?.class?.id,
        class_name: r.session?.class?.name || r.enrollment?.class?.name,
        class_code: r.session?.class?.code || r.enrollment?.class?.code,
        course_title: r.session?.class?.course?.title,
        session: r.session
      }));

      console.log(`ðŸ“‹ Student attendance loaded: ${filtered.length} records`);

      res.json({
        success: true,
        data: {
          records: transformedRecords,
          classSummaries,
          statistics: {
            totalSessions: total,
            presentCount: present,
            absentCount: absent,
            lateCount: late,
            excusedCount: excused,
            attendanceRate: total > 0 ? Math.round(((present + late) / total) * 100) : 0
          }
        }
      });
    } catch (error) {
      console.error('âŒ Error fetching student attendance:', error);
      next(error);
    }
  }
);

