const STUDENT_JOURNEY_STATUS_PRIORITY = {
  active: 1,
  enrolled: 1,
  completed: 2,
  dropped: 3,
  pending: 4,
  waitlisted: 5,
  approved: 6,
  rejected: 7,
  cancelled: 8
};

function getStudentJourneyStatus(enrollmentStatus, requestStatus) {
  if (enrollmentStatus === 'active' || enrollmentStatus === 'enrolled') return 'enrolled';
  if (enrollmentStatus === 'completed') return 'completed';
  if (enrollmentStatus === 'dropped') return 'dropped';
  if (requestStatus === 'pending') return 'pending';
  if (requestStatus === 'waitlisted') return 'waitlisted';
  if (requestStatus === 'approved') return 'approved';
  if (requestStatus === 'rejected') return 'rejected';
  if (requestStatus === 'cancelled') return 'cancelled';
  return null;
}

function getStudentJourneyGroup(status) {
  if (['pending', 'waitlisted', 'approved'].includes(status)) return 'processing';
  if (['enrolled', 'completed', 'dropped', 'rejected', 'cancelled'].includes(status)) return 'history';
  return 'unknown';
}

function getJourneyPriority(status) {
  return STUDENT_JOURNEY_STATUS_PRIORITY[status] || 999;
}

/**
 * GET /api/student/available-courses
 * Browse available courses and classes for enrollment requests
 */
app.get('/api/student/available-courses',
  requireAuth,
  requireRole(['STUDENT']),
  async (req, res, next) => {
    try {
      const supabaseClient = req.supabase || supabase;
      const studentId = req.user.id;
      const centerId = req.user.center_id || req.user.centerId;
      const { search } = req.query;

      let coursesQuery = supabaseClient
        .from('courses')
        .select(`
          id, title, slug, description, cover_image, price, duration_weeks, level,
          classes!inner(
            id, name, code, schedule, room, start_date, end_date, max_students, status, teacher_id,
            teacher:users!classes_teacher_id_fkey(full_name)
          )
        `)
        .eq('status', 'active')
        .eq('classes.center_id', centerId)
        .in('classes.status', ['upcoming', 'ongoing']);

      if (search && String(search).trim()) {
        coursesQuery = coursesQuery.ilike('title', `%${String(search).trim()}%`);
      }

      const { data: courses, error: coursesError } = await coursesQuery;
      if (coursesError) throw coursesError;

      const classIds = (courses || []).flatMap(course => (course.classes || []).map(cls => cls.id));

      let activeEnrollments = [];
      if (classIds.length > 0) {
        const { data, error } = await supabaseClient
          .from('enrollments')
          .select('id, class_id')
          .in('class_id', classIds)
          .eq('status', 'active');
        if (error) throw error;
        activeEnrollments = data || [];
      }

      let requestRows = [];
      if (classIds.length > 0) {
        const { data, error } = await supabaseClient
          .from('enrollment_requests')
          .select('id, class_id, status, created_at')
          .eq('student_id', studentId)
          .eq('center_id', centerId)
          .in('class_id', classIds)
          .order('created_at', { ascending: false });
        if (error) throw error;
        requestRows = data || [];
      }

      const enrolledMap = {};
      for (const enrollment of activeEnrollments) {
        enrolledMap[enrollment.class_id] = (enrolledMap[enrollment.class_id] || 0) + 1;
      }

      const requestStatusMap = {};
      for (const reqRow of requestRows) {
        if (!requestStatusMap[reqRow.class_id]) {
          requestStatusMap[reqRow.class_id] = reqRow.status;
        }
      }

      const data = (courses || []).map(course => ({
        id: course.id,
        title: course.title,
        slug: course.slug,
        description: course.description,
        cover_image: course.cover_image,
        price: course.price,
        duration_weeks: course.duration_weeks,
        level: course.level,
        classes: (course.classes || []).map(cls => {
          const enrolledCount = enrolledMap[cls.id] || 0;
          const maxStudents = cls.max_students || 20;
          return {
            id: cls.id,
            name: cls.name,
            code: cls.code,
            schedule: cls.schedule,
            room: cls.room,
            start_date: cls.start_date,
            end_date: cls.end_date,
            max_students: maxStudents,
            enrolled_count: enrolledCount,
            available_slots: Math.max(0, maxStudents - enrolledCount),
            status: cls.status,
            teacher: cls.teacher,
            request_status: requestStatusMap[cls.id] || null
          };
        })
      }));

      res.json({ success: true, data });
    } catch (error) {
      console.error('Error fetching available courses for student:', error);
      next(error);
    }
  }
);

/**
 * GET /api/student/available-courses/:courseId
 * Get available classes and enrollment/request status for a course
 */
app.get('/api/student/available-courses/:courseId',
  requireAuth,
  requireRole(['STUDENT']),
  async (req, res, next) => {
    try {
      const supabaseClient = req.supabase || supabase;
      const studentId = req.user.id;
      const centerId = req.user.center_id || req.user.centerId;
      const { courseId } = req.params;

      const { data: course, error: courseError } = await supabaseClient
        .from('courses')
        .select(`
          id, title, slug, description, cover_image, price, duration_weeks, level,
          classes!inner(
            id, name, code, schedule, room, start_date, end_date, max_students, status, teacher_id,
            teacher:users!classes_teacher_id_fkey(full_name)
          )
        `)
        .eq('id', courseId)
        .eq('status', 'active')
        .eq('classes.center_id', centerId)
        .in('classes.status', ['upcoming', 'ongoing'])
        .single();

      if (courseError) {
        if (courseError.code === 'PGRST116') {
          return res.status(404).json({ success: false, message: 'KhÃ´ng tÃ¬m tháº¥y khÃ³a há»c' });
        }
        throw courseError;
      }

      const classIds = (course.classes || []).map(cls => cls.id);

      let activeEnrollments = [];
      let myEnrollments = [];
      let requestRows = [];
      if (classIds.length > 0) {
        const [{ data: activeRows, error: activeError }, { data: myRows, error: myError }, { data: reqRows, error: reqError }] = await Promise.all([
          supabaseClient
            .from('enrollments')
            .select('id, class_id')
            .in('class_id', classIds)
            .eq('status', 'active'),
          supabaseClient
            .from('enrollments')
            .select('id, class_id, status')
            .eq('student_id', studentId)
            .in('class_id', classIds),
          supabaseClient
            .from('enrollment_requests')
            .select('id, class_id, status, created_at')
            .eq('student_id', studentId)
            .eq('center_id', centerId)
            .in('class_id', classIds)
            .order('created_at', { ascending: false })
        ]);

        if (activeError) throw activeError;
        if (myError) throw myError;
        if (reqError) throw reqError;

        activeEnrollments = activeRows || [];
        myEnrollments = myRows || [];
        requestRows = reqRows || [];
      }

      const enrolledMap = {};
      for (const enrollment of activeEnrollments) {
        enrolledMap[enrollment.class_id] = (enrolledMap[enrollment.class_id] || 0) + 1;
      }

      const myEnrollmentStatusMap = {};
      for (const enrollment of myEnrollments) {
        if (!myEnrollmentStatusMap[enrollment.class_id]) {
          myEnrollmentStatusMap[enrollment.class_id] = enrollment.status;
        }
      }

      const requestStatusMap = {};
      for (const reqRow of requestRows) {
        if (!requestStatusMap[reqRow.class_id]) {
          requestStatusMap[reqRow.class_id] = reqRow.status;
        }
      }

      const data = {
        id: course.id,
        title: course.title,
        slug: course.slug,
        description: course.description,
        cover_image: course.cover_image,
        price: course.price,
        duration_weeks: course.duration_weeks,
        level: course.level,
        classes: (course.classes || []).map(cls => {
          const enrolledCount = enrolledMap[cls.id] || 0;
          const maxStudents = cls.max_students || 20;
          return {
            id: cls.id,
            name: cls.name,
            code: cls.code,
            schedule: cls.schedule,
            room: cls.room,
            start_date: cls.start_date,
            end_date: cls.end_date,
            max_students: maxStudents,
            enrolled_count: enrolledCount,
            available_slots: Math.max(0, maxStudents - enrolledCount),
            status: cls.status,
            teacher: cls.teacher,
            enrollment_status: myEnrollmentStatusMap[cls.id] || null,
            request_status: requestStatusMap[cls.id] || null,
            journey_status: getStudentJourneyStatus(myEnrollmentStatusMap[cls.id] || null, requestStatusMap[cls.id] || null)
          };
        })
      };

      res.json({ success: true, data });
    } catch (error) {
      console.error('Error fetching available course detail for student:', error);
      next(error);
    }
  }
);

/**
 * GET /api/student/enrollment-journey
 * Student views canonical enrollment journey (requests + enrollments)
 */
app.get('/api/student/enrollment-journey',
  requireAuth,
  requireRole(['STUDENT']),
  async (req, res, next) => {
    try {
      const supabaseClient = req.supabase || supabase;
      const studentId = req.user.id;
      const centerId = req.user.center_id || req.user.centerId;

      const [{ data: enrollmentRows, error: enrollmentError }, { data: requestRows, error: requestError }] = await Promise.all([
        supabaseClient
          .from('enrollments')
          .select(`
            id, class_id, status, created_at, updated_at,
            class:classes!inner(id, name, code, schedule, center_id, course:courses(id, title))
          `)
          .eq('student_id', studentId)
          .eq('class.center_id', centerId)
          .order('updated_at', { ascending: false }),
        supabaseClient
          .from('enrollment_requests')
          .select(`
            id, class_id, status, message, admin_note, created_at, updated_at,
            class:classes!inner(id, name, code, schedule, center_id, course:courses(id, title))
          `)
          .eq('student_id', studentId)
          .eq('center_id', centerId)
          .eq('class.center_id', centerId)
          .order('updated_at', { ascending: false })
      ]);

      if (enrollmentError) throw enrollmentError;
      if (requestError) throw requestError;

      const journeyMap = new Map();

      for (const enrollment of (enrollmentRows || [])) {
        if (!enrollment?.class_id || !enrollment?.class) continue;

        const existing = journeyMap.get(enrollment.class_id) || {};
        const next = {
          ...existing,
          class_id: enrollment.class_id,
          class_name: enrollment.class.name,
          class_code: enrollment.class.code,
          class_schedule: enrollment.class.schedule,
          course_id: enrollment.class.course?.id || null,
          course_name: enrollment.class.course?.title || null,
          enrollment_id: enrollment.id,
          enrollment_status: enrollment.status,
          enrollment_created_at: enrollment.created_at,
          enrollment_updated_at: enrollment.updated_at
        };

        journeyMap.set(enrollment.class_id, next);
      }

      for (const request of (requestRows || [])) {
        if (!request?.class_id || !request?.class) continue;

        const existing = journeyMap.get(request.class_id) || {};
        const next = {
          ...existing,
          class_id: request.class_id,
          class_name: existing.class_name || request.class.name,
          class_code: existing.class_code || request.class.code,
          class_schedule: existing.class_schedule || request.class.schedule,
          course_id: existing.course_id || request.class.course?.id || null,
          course_name: existing.course_name || request.class.course?.title || null,
          request_id: request.id,
          request_status: request.status,
          request_message: request.message,
          request_admin_note: request.admin_note,
          request_created_at: request.created_at,
          request_updated_at: request.updated_at
        };

        journeyMap.set(request.class_id, next);
      }

      const items = Array.from(journeyMap.values())
        .map((row) => {
          const status = getStudentJourneyStatus(row.enrollment_status, row.request_status);
          const status_group = getStudentJourneyGroup(status);
          const can_cancel = Boolean(row.request_id) && ['pending', 'waitlisted'].includes(row.request_status);

          return {
            id: `journey-${row.class_id}`,
            class_id: row.class_id,
            class_name: row.class_name,
            class_code: row.class_code,
            class_schedule: row.class_schedule,
            course_id: row.course_id,
            course_name: row.course_name,
            status,
            status_group,
            enrollment_id: row.enrollment_id || null,
            enrollment_status: row.enrollment_status || null,
            request_id: row.request_id || null,
            request_status: row.request_status || null,
            request_message: row.request_message || null,
            request_admin_note: row.request_admin_note || null,
            can_cancel,
            created_at: row.request_created_at || row.enrollment_created_at || null,
            updated_at: row.request_updated_at || row.enrollment_updated_at || row.request_created_at || row.enrollment_created_at || null
          };
        })
        .filter((row) => row.status)
        .sort((a, b) => {
          const priorityDiff = getJourneyPriority(a.status) - getJourneyPriority(b.status);
          if (priorityDiff !== 0) return priorityDiff;
          return new Date(b.updated_at || 0).getTime() - new Date(a.updated_at || 0).getTime();
        });

      const groups = {
        processing: items.filter((item) => item.status_group === 'processing'),
        history: items.filter((item) => item.status_group === 'history')
      };

      res.json({
        success: true,
        data: {
          items,
          groups,
          summary: {
            total: items.length,
            processing_count: groups.processing.length,
            history_count: groups.history.length
          }
        }
      });
    } catch (error) {
      console.error('Error fetching student enrollment journey:', error);
      next(error);
    }
  }
);

/**
 * POST /api/student/enrollment-requests
 * Student submits enrollment request
 */
app.post('/api/student/enrollment-requests',
  requireAuth,
  requireRole(['STUDENT']),
  async (req, res, next) => {
    try {
      const supabaseClient = req.supabase || supabase;
      const studentId = req.user.id;
      const centerId = req.user.center_id || req.user.centerId;
      const { class_id, message } = req.body;

      if (!class_id) {
        return res.status(400).json({ success: false, message: 'Thiáº¿u class_id' });
      }

      const { data: classData, error: classError } = await supabaseClient
        .from('classes')
        .select('id, name, center_id, status, max_students')
        .eq('id', class_id)
        .eq('center_id', centerId)
        .single();

      if (classError) {
        if (classError.code === 'PGRST116') {
          return res.status(404).json({ success: false, message: 'KhÃ´ng tÃ¬m tháº¥y lá»›p há»c' });
        }
        throw classError;
      }

      if (!['upcoming', 'ongoing'].includes(classData.status)) {
        return res.status(400).json({ success: false, message: 'Chá»‰ cÃ³ thá»ƒ gá»­i yÃªu cáº§u cho lá»›p sáº¯p khai giáº£ng hoáº·c Ä‘ang má»Ÿ' });
      }

      const { data: activeEnrollment, error: activeEnrollError } = await supabaseClient
        .from('enrollments')
        .select('id')
        .eq('student_id', studentId)
        .eq('class_id', class_id)
        .eq('status', 'active')
        .maybeSingle();
      if (activeEnrollError) throw activeEnrollError;

      if (activeEnrollment) {
        return res.status(400).json({ success: false, message: 'Báº¡n Ä‘Ã£ ghi danh vÃ o lá»›p nÃ y' });
      }

      const { data: existingRequest, error: existingRequestError } = await supabaseClient
        .from('enrollment_requests')
        .select('id, status')
        .eq('student_id', studentId)
        .eq('class_id', class_id)
        .in('status', ['pending', 'waitlisted'])
        .maybeSingle();
      if (existingRequestError) throw existingRequestError;

      if (existingRequest) {
        return res.status(400).json({ success: false, message: 'Báº¡n Ä‘Ã£ cÃ³ yÃªu cáº§u chá» xá»­ lÃ½ cho lá»›p nÃ y' });
      }

      const { count: enrolledCount, error: enrolledCountError } = await supabaseClient
        .from('enrollments')
        .select('id', { count: 'exact', head: true })
        .eq('class_id', class_id)
        .eq('status', 'active');
      if (enrolledCountError) throw enrolledCountError;

      const maxStudents = classData.max_students || 20;
      const initialStatus = (enrolledCount || 0) < maxStudents ? 'pending' : 'waitlisted';

      const { data: createdRequest, error: createError } = await supabaseClient
        .from('enrollment_requests')
        .insert({
          student_id: studentId,
          class_id,
          center_id: centerId,
          status: initialStatus,
          message: message || null
        })
        .select('id, student_id, class_id, center_id, status, message, admin_note, reviewed_by, reviewed_at, created_at, updated_at')
        .single();
      if (createError) throw createError;

      const { data: studentData } = await supabaseClient
        .from('users')
        .select('id, full_name')
        .eq('id', studentId)
        .single();

      const { data: managers } = await supabaseClient
        .from('users')
        .select('id, roles!inner(code)')
        .eq('center_id', centerId)
        .eq('roles.code', 'CENTER_MANAGER');

      const studentName = studentData?.full_name || 'Há»c viÃªn';
      const className = classData?.name || 'lá»›p há»c';
      for (const mgr of (managers || [])) {
        createNotification(supabaseClient, {
          userId: mgr.id,
          centerId,
          type: 'enrollment_request',
          title: 'YÃªu cáº§u Ä‘Äƒng kÃ½ má»›i',
          message: `${studentName} yÃªu cáº§u Ä‘Äƒng kÃ½ lá»›p ${className}`,
          referenceId: createdRequest.id,
          referenceType: 'enrollment_request'
        }).catch(err => console.warn('Manager notification failed:', err.message));
      }

      res.status(201).json({ success: true, data: createdRequest });
    } catch (error) {
      console.error('Error creating student enrollment request:', error);
      next(error);
    }
  }
);

