/**
 * GET /api/parent/child/:studentId/schedule
 * Get schedule for a linked child
 * ðŸ”’ PARENT only (must have link to student)
 */
app.get('/api/parent/child/:studentId/schedule',
  requireAuth,
  requireRole(['PARENT']),
  async (req, res, next) => {
    try {
      const parentId = req.user.id;
      const { studentId } = req.params;

      // Verify parent has access to this student
      const { data: link, error: linkError } = await supabase
        .from('parent_student_links')
        .select('id, can_view_academics')
        .eq('parent_id', parentId)
        .eq('student_id', studentId)
        .eq('status', 'active')
        .single();

      if (linkError || !link) {
        return res.status(403).json({
          success: false,
          message: 'Báº¡n khÃ´ng cÃ³ quyá»n xem thÃ´ng tin há»c viÃªn nÃ y'
        });
      }

      // Get enrolled classes
      const { data: enrollments, error } = await supabase
        .from('enrollments')
        .select(`
          id,
          class:classes(
            id, name, code, schedule, start_date, end_date, room,
            course:courses(id, title, color),
            teacher:users!classes_teacher_id_fkey(id, full_name)
          )
        `)
        .eq('student_id', studentId)
        .eq('status', 'active');

      if (error) throw error;

      // Generate schedule events
      const events = [];
      for (const enrollment of enrollments || []) {
        const cls = enrollment.class;
        if (!cls?.schedule) continue;

        for (const scheduleItem of cls.schedule) {
          events.push({
            classId: cls.id,
            className: cls.name,
            classCode: cls.code,
            courseId: cls.course?.id,
            courseName: cls.course?.title,
            courseTitle: cls.course?.title,
            teacherName: cls.teacher?.full_name,
            roomName: cls.room,
            room: cls.room,
            dayOfWeek: scheduleItem.day,
            startTime: scheduleItem.start,
            endTime: scheduleItem.end,
            startDate: cls.start_date,
            endDate: cls.end_date
          });
        }
      }

      events.sort((a, b) => {
        if (a.dayOfWeek !== b.dayOfWeek) return a.dayOfWeek - b.dayOfWeek;
        return a.startTime.localeCompare(b.startTime);
      });

      console.log(`ðŸ“… Parent viewing child schedule: ${events.length} events`);

      res.json({
        success: true,
        data: {
          events,
          classes: (enrollments || []).map(e => ({
            id: e.class?.id,
            name: e.class?.name,
            code: e.class?.code,
            courseTitle: e.class?.course?.title
          }))
        }
      });
    } catch (error) {
      console.error('âŒ Error fetching child schedule:', error);
      next(error);
    }
  }
);

/**
 * GET /api/parent/child/:studentId/grades
 * Get grades for a linked child
 * ðŸ”’ PARENT only (must have link with can_view_academics=true)
 */
app.get('/api/parent/child/:studentId/grades',
  requireAuth,
  requireRole(['PARENT']),
  async (req, res, next) => {
    try {
      const parentId = req.user.id;
      const { studentId } = req.params;

      // Verify parent has access with academic viewing permission
      const { data: link, error: linkError } = await supabase
        .from('parent_student_links')
        .select('id, can_view_academics')
        .eq('parent_id', parentId)
        .eq('student_id', studentId)
        .eq('status', 'active')
        .single();

      if (linkError || !link) {
        return res.status(403).json({
          success: false,
          message: 'Báº¡n khÃ´ng cÃ³ quyá»n xem thÃ´ng tin há»c viÃªn nÃ y'
        });
      }

      if (!link.can_view_academics) {
        return res.status(403).json({
          success: false,
          message: 'Báº¡n khÃ´ng cÃ³ quyá»n xem Ä‘iá»ƒm cá»§a há»c viÃªn nÃ y'
        });
      }

      // Get grades
      const { data: grades, error } = await supabase
        .from('grades')
        .select(`
          id, score, grade_type, assessment_date, notes,
          class:classes(id, name, code, course:courses(id, title))
        `)
        .eq('student_id', studentId)
        .order('assessment_date', { ascending: false });

      if (error) throw error;

      // Group by class
      const gradesByClass = {};
      for (const grade of grades || []) {
        const classId = grade.class?.id;
        if (!classId) continue;
        
        if (!gradesByClass[classId]) {
          gradesByClass[classId] = {
            classId,
            className: grade.class.name,
            classCode: grade.class.code,
            courseTitle: grade.class.course?.title,
            grades: []
          };
        }
        gradesByClass[classId].grades.push({
          id: grade.id,
          score: grade.score,
          gradeType: grade.grade_type,
          assessmentDate: grade.assessment_date,
          notes: grade.notes
        });
      }

      console.log(`ðŸ“Š Parent viewing child grades: ${grades?.length || 0} grades`);

      res.json({
        success: true,
        data: {
          gradesByClass: Object.values(gradesByClass),
          totalGrades: grades?.length || 0
        }
      });
    } catch (error) {
      console.error('âŒ Error fetching child grades:', error);
      next(error);
    }
  }
);

/**
 * GET /api/parent/child/:studentId/attendance
 * Get attendance for a linked child
 * ðŸ”’ PARENT only (must have link with can_view_academics=true)
 */
app.get('/api/parent/child/:studentId/attendance',
  requireAuth,
  requireRole(['PARENT']),
  async (req, res, next) => {
    try {
      const parentId = req.user.id;
      const { studentId } = req.params;
      const { classId } = req.query;

      // Verify parent has access
      const { data: link, error: linkError } = await supabase
        .from('parent_student_links')
        .select('id, can_view_academics')
        .eq('parent_id', parentId)
        .eq('student_id', studentId)
        .eq('status', 'active')
        .single();

      if (linkError || !link) {
        return res.status(403).json({
          success: false,
          message: 'Báº¡n khÃ´ng cÃ³ quyá»n xem thÃ´ng tin há»c viÃªn nÃ y'
        });
      }

      if (!link.can_view_academics) {
        return res.status(403).json({
          success: false,
          message: 'Báº¡n khÃ´ng cÃ³ quyá»n xem Ä‘iá»ƒm danh cá»§a há»c viÃªn nÃ y'
        });
      }

      // Get enrollments first
      let enrollmentsQuery = supabase
        .from('enrollments')
        .select('id, class:classes(id, name, code)')
        .eq('student_id', studentId)
        .eq('status', 'active');

      if (classId) {
        enrollmentsQuery = enrollmentsQuery.eq('class_id', classId);
      }

      const { data: enrollments, error: enrollError } = await enrollmentsQuery;
      if (enrollError) throw enrollError;

      const enrollmentIds = (enrollments || []).map(e => e.id);

      // Get attendance records
      const { data: attendance, error } = await supabase
        .from('attendance')
        .select(`
          id, session_date, session_number, status, notes,
          enrollment:enrollments(
            id,
            class:classes(id, name, code)
          )
        `)
        .in('enrollment_id', enrollmentIds)
        .order('session_date', { ascending: false });

      if (error) throw error;

      // Calculate stats
      const total = attendance?.length || 0;
      const present = (attendance || []).filter(a => a.status === 'present').length;
      const absent = (attendance || []).filter(a => a.status === 'absent').length;
      const late = (attendance || []).filter(a => a.status === 'late').length;
      const excused = (attendance || []).filter(a => a.status === 'excused').length;
      const attendanceRate = total > 0 ? Math.round((present + late) / total * 100) : 0;

      console.log(`ðŸ“‹ Parent viewing child attendance: ${total} records`);

      res.json({
        success: true,
        data: {
          attendance: (attendance || []).map(a => ({
            id: a.id,
            sessionDate: a.session_date,
            sessionNumber: a.session_number,
            status: a.status,
            notes: a.notes,
            className: a.enrollment?.class?.name,
            classCode: a.enrollment?.class?.code
          })),
          stats: {
            total,
            present,
            absent,
            late,
            excused,
            attendanceRate
          },
          classes: (enrollments || []).map(e => ({
            id: e.class?.id,
            name: e.class?.name,
            code: e.class?.code
          }))
        }
      });
    } catch (error) {
      console.error('âŒ Error fetching child attendance:', error);
      next(error);
    }
  }
);

